import React, { useContext } from "react";
import { Link, useNavigate } from "react-router-dom";
import { CartContext } from "../context/CartContext";

function Stars({ v }) {
  const n = Math.round(v || 0);
  return (
    <div style={{ display: "flex", gap: 4 }}>
      {Array.from({ length: 5 }).map((_, i) => (
        <span key={i} style={{ color: i < n ? "#f59e0b" : "#e6e7ea" }}>
          ★
        </span>
      ))}
    </div>
  );
}

export default function ProductCard({ product }) {
  const nav = useNavigate();
  const { addToCart } = useContext(CartContext);

  const onAdd = (e) => {
    e.preventDefault();
    addToCart(product, 1);
    // small feedback could be added here
    alert("Added to cart");
  };

  const onBuyNow = (e) => {
    e.preventDefault();
    addToCart(product, 1);
    nav("/checkout");
  };

  const img =
    (product.images && product.images[0]) ||
    (product.image || product.imageUrl) ||
    "/images/placeholder.png";

  const price = product.discount_price || product.price;
  const old = product.discount_price ? product.price : null;
  const discount = product.discount_price
    ? Math.round(100 - (product.discount_price / product.price) * 100)
    : 0;

  return (
    <Link to={`/product/${product.id}`} className="product-card">
      <div className="product-thumb" style={{ backgroundImage: `url(${img})` }} />
      <div className="product-body">
        <h4 className="product-title">{product.name}</h4>
        <div className="product-price">
          <strong>₹{product.discount_price || product.price}</strong>
          {product.discount_price && (
            <span className="muted">
              {" "}
              <del>₹{product.price}</del>
            </span>
          )}
        </div>
        <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
          <button className="btn small" onClick={onAdd} type="button">
            Add to cart
          </button>
          <button className="btn primary small" onClick={onBuyNow} type="button">
            Buy now
          </button>
        </div>
      </div>
    </Link>
  );
}
